create function public.start_experimental_jev_v12(p_user uuid,p_source uuid,p_configuration text,p_confirm_cost boolean,p_prepared jsonb)
returns uuid language plpgsql security invoker set search_path='' as $$
declare s public.analysis_negative_ai_exploratory_runs;c public.analysis_jev_experimental_configurations;r uuid;expected jsonb;item jsonb;src jsonb;ref jsonb;base public.analysis_negative_validation_ai_preannotations;recheck record;expected_choice text;task jsonb;source_task public.analysis_negative_ai_exploratory_tasks;n integer;
begin
 select * into s from public.analysis_negative_ai_exploratory_runs where id=p_source and status='completed';
 if s.id is null or s.id<>'adfa4fdf-a8c7-4976-916f-339ebabb8d62'::uuid or s.source_experiment_id<>'a80c5a80-c322-4c13-85d4-e7506f91ec93'::uuid or not exists(select 1 from public.organization_members where organization_id=s.organization_id and user_id=p_user and role in ('owner','admin','manager')) then raise exception 'FORBIDDEN';end if;
 if p_confirm_cost is distinct from true then raise exception 'V12_PAYMENT_CONFIRMATION_REQUIRED';end if;
 select * into c from public.analysis_jev_experimental_configurations where id=p_configuration and analysis_version=12;
 if c.id is null or c.config_sha256 is distinct from p_prepared->>'config_sha256' or c.config->>'production_enabled' is distinct from 'false' then raise exception 'V12_CONFIG_NOT_FROZEN';end if;
 perform pg_advisory_xact_lock(hashtextextended('v12:'||p_source::text||p_configuration,0));select id into r from public.analysis_jev_v12_runs where source_benchmark_id=p_source and configuration_id=p_configuration;if found then return r;end if;
 select jsonb_agg(x->>'review_id' order by (x->>'position')::integer) into expected from jsonb_array_elements(s.dataset_snapshot) x where
 (select count(*) from public.analysis_negative_ai_exploratory_tasks t where t.run_id=s.id and t.review_id::text=x->>'review_id' and t.model_version='v9' and t.status='completed' and (select count(*) from jsonb_object_keys(t.response->'themes'))=25)=3
 and (select count(*) from public.analysis_negative_ai_exploratory_tasks t where t.run_id=s.id and t.review_id::text=x->>'review_id' and t.model_version='v11' and t.status='completed' and (select count(*) from jsonb_object_keys(t.response->'themes'))=25)=3;
 if expected is null or expected is distinct from (select jsonb_agg(x->>'review_id' order by (x->>'position')::integer) from jsonb_array_elements(p_prepared->'items') x) then raise exception 'V12_PAIRED_COHORT_CHANGED';end if;
 n=jsonb_array_length(expected);
 if (p_prepared->>'expected_requests')::integer<>n*3 or jsonb_array_length(p_prepared->'reference')<>n*25 or jsonb_array_length(p_prepared->'baseline')<>n*3 or (select count(distinct (x->>'review_id')||':'||(x->>'theme_key')) from jsonb_array_elements(p_prepared->'reference') x)<>n*25 then raise exception 'V12_PREPARED_INVALID';end if;
 for item in select * from jsonb_array_elements(p_prepared->'items') loop
 select x into src from jsonb_array_elements(s.dataset_snapshot) x where x->>'review_id'=item->>'review_id';
 if src is null or src->>'analysis_language' is distinct from 'en' or src->>'analysis_text' is distinct from item->>'analysis_text' or src->>'analysis_text_sha256' is distinct from item->>'analysis_text_sha256' or encode(extensions.digest(item->>'analysis_text','sha256'),'hex') is distinct from item->>'analysis_text_sha256' or src->'normalized_category_ratings' is distinct from item->'normalized_category_ratings' or src->'overall_rating' is distinct from item->'overall_rating' then raise exception 'V12_FROZEN_TEXT_CHANGED';end if;
 if exists(select 1 from public.analysis_v11_independent_holdout_items h where h.holdout_id='d7d7142c-03ef-48c3-b36e-bacf6d923f40'::uuid and h.review_id::text=item->>'review_id') then raise exception 'V12_HOLDOUT_PROTECTED';end if;
 end loop;
 for ref in select * from jsonb_array_elements(p_prepared->'reference') loop
 if not(expected ? (ref->>'review_id')) or not(c.config->'thresholds' ? (ref->>'theme_key')) then raise exception 'V12_REFERENCE_CHANGED';end if;
 select * into base from public.analysis_negative_validation_ai_preannotations where experiment_id=s.source_experiment_id and review_id=(ref->>'review_id')::uuid;
 if base.review_id is null or base.theme_choices->>(ref->>'theme_key') is distinct from ref->>'initial_choice' then raise exception 'V12_REFERENCE_CHANGED';end if;
 select * into recheck from public.analysis_negative_ai_theme_rechecks where exploratory_run_id=s.id and review_id=(ref->>'review_id')::uuid and theme_key=ref->>'theme_key';
 if found then
 expected_choice=case when recheck.judgement='uncertain' then 'uncertain' else recheck.reviewed_ai_choice end;
 if recheck.initial_ai_choice is distinct from ref->>'initial_choice' or ref->>'origin' is distinct from 'chatgpt_ai_recheck' then raise exception 'V12_REFERENCE_CHANGED';end if;
 else expected_choice=ref->>'initial_choice';if ref->>'origin' is distinct from 'chatgpt_initial_ai' then raise exception 'V12_REFERENCE_CHANGED';end if;
 end if;
 if expected_choice is distinct from ref->>'choice' then raise exception 'V12_REFERENCE_CHANGED';end if;
 end loop;
 for task in select * from jsonb_array_elements(p_prepared->'baseline') loop
 select * into source_task from public.analysis_negative_ai_exploratory_tasks where id=(task->>'id')::uuid and run_id=s.id and model_version='v11' and status='completed';
 if source_task.id is null or not(expected ? source_task.review_id::text) or source_task.response is distinct from task->'response' or source_task.review_id::text is distinct from task->>'review_id' or source_task.repeat is distinct from (task->>'repeat')::integer then raise exception 'V12_BASELINE_CHANGED';end if;
 end loop;
 insert into public.analysis_jev_v12_runs(organization_id,establishment_id,source_benchmark_id,configuration_id,config,prepared,created_by)
 values(s.organization_id,s.establishment_id,s.id,c.id,c.config,p_prepared,p_user) returning id into r;
 insert into public.analysis_jev_v12_tasks(run_id,review_id,analysis_text_sha256,review_alias,question_set,repeat)
 select r,(x->>'review_id')::uuid,x->>'analysis_text_sha256','r'||(x->>'position'),c.id,rep from jsonb_array_elements(p_prepared->'items') x cross join generate_series(1,3) rep;return r;
end $$;
create function public.claim_experimental_v12_run(p_worker uuid) returns jsonb language plpgsql security invoker set search_path='' as $$
declare r public.analysis_jev_v12_runs;
begin
 perform pg_advisory_xact_lock(hashtextextended('v12-worker',0));
 if exists(select 1 from public.analysis_jev_v12_runs where status='running' and lease_until>now()) then return null;end if;
 select * into r from public.analysis_jev_v12_runs where status='queued' or(status='running' and (lease_until is null or lease_until<=now())) order by created_at for update skip locked limit 1;if not found then return null;end if;
 update public.analysis_jev_v12_tasks set status='failed',error_code='JEV_RESPONSE_UNCONFIRMED',usage_complete=false,completed_at=now() where run_id=r.id and status='running';
 update public.analysis_jev_v12_runs set status='running',lease_owner=p_worker,lease_until=now()+interval '240 seconds',started_at=coalesce(started_at,now()) where id=r.id returning * into r;return to_jsonb(r);
end $$;
create function public.claim_experimental_v12_tasks(p_id uuid,p_worker uuid) returns setof public.analysis_jev_v12_tasks language plpgsql security invoker set search_path='' as $$
begin
 if not exists(select 1 from public.analysis_jev_v12_runs where id=p_id and status='running' and lease_owner=p_worker and lease_until>now()) then raise exception 'V12_LEASE_LOST';end if;
 return query update public.analysis_jev_v12_tasks set status='running',lease_owner=p_worker,started_at=now() where id in(select id from public.analysis_jev_v12_tasks where run_id=p_id and status='pending' order by review_id,repeat for update skip locked limit 8) returning *;
end $$;
create function public.complete_experimental_v12_task(p_id uuid,p_worker uuid,p_task uuid,p_values jsonb) returns boolean language plpgsql security invoker set search_path='' as $$
declare r public.analysis_jev_v12_runs;
begin
 select * into r from public.analysis_jev_v12_runs where id=p_id and status='running' and lease_owner=p_worker and lease_until>now() for update;if not found then return false;end if;
 update public.analysis_jev_v12_tasks set status=p_values->>'status',response=p_values->'response',served_model=p_values->>'served_model',input_tokens=(p_values->>'input_tokens')::bigint,output_tokens=(p_values->>'output_tokens')::bigint,request_count=(p_values->>'request_count')::integer,retry_count=0,cost_usd=(p_values->>'input_tokens')::double precision/1000000*(r.prepared->>'input_rate')::double precision,duration_ms=(p_values->>'duration_ms')::bigint,error_code=p_values->>'error_code',usage_complete=(p_values->>'usage_complete')::boolean,completed_at=now() where id=p_task and run_id=p_id and status='running' and lease_owner=p_worker;if not found then return false;end if;
 update public.analysis_jev_v12_runs set lease_until=now()+interval '240 seconds' where id=p_id;return true;
end $$;
create function public.finish_experimental_v12_tick(p_id uuid,p_worker uuid,p_comparison jsonb default null,p_error text default null) returns boolean language plpgsql security invoker set search_path='' as $$
declare r public.analysis_jev_v12_runs;
begin
 select * into r from public.analysis_jev_v12_runs where id=p_id and status='running' and lease_owner=p_worker and lease_until>now() for update;if not found then return false;end if;
 if p_error is not null then update public.analysis_jev_v12_runs set status='failed',error_code=p_error,completed_at=now(),lease_owner=null,lease_until=null where id=p_id;
 elsif p_comparison is not null then
 if exists(select 1 from public.analysis_jev_v12_tasks where run_id=p_id and status in ('pending','running')) or (select count(*) from public.analysis_jev_v12_tasks where run_id=p_id)<>(r.prepared->>'expected_requests')::integer or p_comparison->>'human_validated' is distinct from 'false' or p_comparison->>'production_enabled' is distinct from 'false' then raise exception 'V12_RESULT_INVALID';end if;
 insert into public.analysis_jev_v12_results(run_id,comparison) values(p_id,p_comparison);
 update public.analysis_jev_v12_runs set status='completed',completed_at=now(),lease_owner=null,lease_until=null where id=p_id;
 else update public.analysis_jev_v12_runs set lease_owner=null,lease_until=null where id=p_id;end if;return true;
end $$;
revoke all on function public.experimental_v12_guard(),public.start_experimental_jev_v12(uuid,uuid,text,boolean,jsonb),public.claim_experimental_v12_run(uuid),public.claim_experimental_v12_tasks(uuid,uuid),public.complete_experimental_v12_task(uuid,uuid,uuid,jsonb),public.finish_experimental_v12_tick(uuid,uuid,jsonb,text) from public,anon,authenticated;
grant execute on function public.start_experimental_jev_v12(uuid,uuid,text,boolean,jsonb),public.claim_experimental_v12_run(uuid),public.claim_experimental_v12_tasks(uuid,uuid),public.complete_experimental_v12_task(uuid,uuid,uuid,jsonb),public.finish_experimental_v12_tick(uuid,uuid,jsonb,text) to service_role;
select cron.schedule('home-reviews-experimental-v12-worker-v1','* * * * *',$cron$
 select net.http_post(url:='https://ihuztjkblywzjdruusdj.supabase.co/functions/v1/process-experimental-jev-v12',headers:=jsonb_build_object('Content-Type','application/json','x-home-reviews-scheduler',(select decrypted_secret from vault.decrypted_secrets where name='home_reviews_scheduler_token')),body:='{}'::jsonb,timeout_milliseconds:=180000)
 where exists(select 1 from public.analysis_jev_v12_runs where status in ('queued','running') and (lease_until is null or lease_until<=now()));
$cron$);
